tests/prune_test.sh.text:
#!/bin/bash
# prune: a dry run on an empty root exits 0; audit logs live in var/audit and are kept 400 days (ADR-0015).
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
mkdir -p "$d/var/audit" "$d/var/log/audit"
touch -d '401 days ago' "$d/var/audit/old.log" "$d/var/log/audit/other.log"
touch -d '399 days ago' "$d/var/audit/recent.log"
touch -d '100 days ago' "$d/var/audit/mid.log"
RELAY_ROOT=$d bash bin/prune >/dev/null
[ ! -e "$d/var/audit/old.log" ] || { echo "old audit log not pruned"; fail=1; }
[ -e "$d/var/audit/recent.log" ] || { echo "399-day audit log pruned early"; fail=1; }
[ -e "$d/var/audit/mid.log" ] || { echo "100-day audit log pruned early"; fail=1; }
[ -e "$d/var/log/audit/other.log" ] || { echo "var/log/audit touched"; fail=1; }
rm -rf "$d"
exit $fail

