tests/prune_test.sh.text:
#!/bin/bash
# prune: a dry run on an empty root exits 0 and removes nothing.
# Audit logs live in var/audit and are kept 400 days (ADR-0015).
fail=0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '399 days ago' "$d/var/audit/keep399.log"
touch -d '100 days ago' "$d/var/audit/keep100.log"
touch -d '401 days ago' "$d/var/log/shift/other.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run)
[ "$out" = "$d/var/audit/old.log" ] || { echo "dry-run list: $out"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ ! -e "$d/var/audit/old.log" ] || { echo "old audit not removed"; fail=1; }
[ -e "$d/var/audit/keep399.log" ] && [ -e "$d/var/audit/keep100.log" ] || { echo "audit within retention removed"; fail=1; }
[ -e "$d/var/log/shift/other.log" ] || { echo "non-audit touched"; fail=1; }
rm -rf "$d"
exit $fail

