lib/prune/paths.sh.text:
#!/bin/bash
# Paths the prune job touches. Audit logs live under var/audit (ADR-0015, docs/runbook.md:35);
# var/log is operational logs only (ADR-0016) and is not pruned here.
PRUNE_AUDIT_DIR=var/audit
prune_root() { echo "${RELAY_ROOT:-.}"; }
prune_audit_dir() { echo "$(prune_root)/$PRUNE_AUDIT_DIR"; }

lib/prune/retention.sh.text:
#!/bin/bash
# Retention for audit logs: 400 days (ADR-0015, docs/adr/0015-audit-log-retention.md:18).
PRUNE_KEEP_DAYS=400
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
# -mtime +N matches files at least N+1 days old, so +400 never removes a file younger than 401 days.
prune_find_args() { echo "-type f -mtime +$(prune_keep_days)"; }

