lib/prune/paths.sh.text:
#!/bin/bash
# Paths the prune job touches. Audit logs live under var/audit (ADR-0015), not var/log.
PRUNE_AUDIT_DIR=var/audit
prune_root() { echo "${RELAY_ROOT:-.}"; }
prune_audit_dir() { echo "$(prune_root)/$PRUNE_AUDIT_DIR"; }

lib/prune/retention.sh.text:
#!/bin/bash
# Retention for audit logs: 400 days (ADR-0015). Partner reconciliation needs 13 months.
PRUNE_KEEP_DAYS=400
prune_keep_days() { echo "$PRUNE_KEEP_DAYS"; }
# find -mtime +N matches files whose age in whole days is > N, so nothing younger than 401 days is removed.
prune_find_args() { echo "-type f -mtime +$(prune_keep_days)"; }

