tests/prune_test.sh.text:
#!/bin/bash
# prune: sweeps var/audit (ADR-0015) with a 400-day retention; never var/log.
fail=0
d=$(mktemp -d)
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '399 days ago' "$d/var/audit/keep.log"
touch -d '100 days ago' "$d/var/audit/recent.log"
touch -d '500 days ago' "$d/var/log/shift/other.log"
out=$(RELAY_ROOT=$d bash bin/prune --dry-run) || { echo "prune dry-run"; fail=1; }
[ "$out" = "$d/var/audit/old.log" ] || { echo "dry-run lists: $out"; fail=1; }
[ -e "$d/var/audit/old.log" ] || { echo "dry-run removed"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null
[ ! -e "$d/var/audit/old.log" ] || { echo "old not removed"; fail=1; }
[ -e "$d/var/audit/keep.log" ] && [ -e "$d/var/audit/recent.log" ] || { echo "kept file removed"; fail=1; }
[ -e "$d/var/log/shift/other.log" ] || { echo "touched var/log"; fail=1; }
rm -rf "$d"
# empty root exits 0
d=$(mktemp -d)
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "empty root"; fail=1; }
rm -rf "$d"
exit $fail

