tests/prune_test.sh.text:
#!/bin/bash
# prune: removes audit files past 400 days under var/audit (ADR-0015), keeps newer ones and var/log/shift.
fail=0
d=$(mktemp -d)
mkdir -p "$d/var/audit" "$d/var/log/shift"
touch -d '401 days ago' "$d/var/audit/old.log"
touch -d '399 days ago' "$d/var/audit/keep399.log"
touch -d '100 days ago' "$d/var/audit/keep100.log"
touch -d '500 days ago' "$d/var/log/shift/other.log"
RELAY_ROOT=$d bash bin/prune --dry-run >/dev/null || { echo "prune dry-run"; fail=1; }
[ -e "$d/var/audit/old.log" ] || { echo "dry-run removed a file"; fail=1; }
RELAY_ROOT=$d bash bin/prune >/dev/null || { echo "prune run"; fail=1; }
[ ! -e "$d/var/audit/old.log" ] || { echo "old audit not removed"; fail=1; }
[ -e "$d/var/audit/keep399.log" ] || { echo "399d audit removed"; fail=1; }
